export interface Preferences {
  theme: string;
  notifications: boolean;
  language: string;
}

export type Metadata = Record<string, unknown>;

export interface User {
  id: number;
  name: string;
  email: string;
  preferences: Preferences;
  tags: string[];
  last_login: string; // ISO 8601 datetime, e.g. "2024-01-15T10:30:00Z"
  metadata?: Metadata | null | undefined;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === "object" &&
    value !== null &&
    !Array.isArray(value)
  );
}

function isStringArray(value: unknown): value is string[] {
  return (
    Array.isArray(value) &&
    value.every((item) => typeof item === "string")
  );
}

export function validateUser(value: unknown): value is User {
  if (!isRecord(value)) {
    return false;
  }

  const user = value;

  if (typeof user.id !== "number" || !Number.isInteger(user.id)) {
    return false;
  }

  const name = user.name;
  if (typeof name !== "string" || name.length === 0) {
    return false;
  }

  const email = user.email;
  if (typeof email !== "string" || !email.includes("@")) {
    return false;
  }

  const preferences = user.preferences;
  if (!isRecord(preferences)) {
    return false;
  }

  if (typeof preferences.theme !== "string") {
    return false;
  }

  if (typeof preferences.notifications !== "boolean") {
    return false;
  }

  if (typeof preferences.language !== "string") {
    return false;
  }

  if (!isStringArray(user.tags)) {
    return false;
  }

  const lastLogin = user.last_login;
  if (typeof lastLogin !== "string" || lastLogin.length === 0) {
    return false;
  }

  if ("metadata" in user) {
    const metadata = user.metadata;

    if (
      metadata !== null &&
      metadata !== undefined &&
      !isRecord(metadata)
    ) {
      return false;
    }
  }

  return true;
}
