#!/usr/bin/env python3
"""
Summarize log level counts for .log files in a directory.

Usage:
    python log_summary.py /path/to/logs --min-errors 3
"""

import argparse
import re
import sys
from pathlib import Path

LOG_LEVELS = ("INFO", "WARN", "ERROR", "DEBUG")
LEVEL_PATTERNS = {level: re.compile(rf"\b{level}\b") for level in LOG_LEVELS}


def count_log_levels(path: Path) -> dict:
    """
    Count log level occurrences in a single file.

    A line is counted once for each log level that appears as a whole word.
    """
    counts = {level: 0 for level in LOG_LEVELS}

    try:
        with path.open("r", encoding="utf-8", errors="replace") as handle:
            for line in handle:
                for level in LOG_LEVELS:
                    if LEVEL_PATTERNS[level].search(line):
                        counts[level] += 1
    except OSError as exc:
        print(f"Warning: could not read {path}: {exc}", file=sys.stderr)

    return counts


def print_summary(rows: list) -> None:
    """
    Print a formatted summary table.

    rows: list of tuples:
        (filename, {"INFO": int, "WARN": int, "ERROR": int, "DEBUG": int})
    """
    headers = ["file", *LOG_LEVELS]

    if rows:
        widths = [
            max(len(headers[0]), max(len(row[0]) for row in rows))
        ]

        for index, level in enumerate(LOG_LEVELS, start=1):
            widths.append(
                max(len(level), max(len(str(row[index])) for row in rows))
            )
    else:
        widths = [len(header) for header in headers]

    print(" | ".join(header.ljust(width) for header, width in zip(headers, widths)).rstrip())
    print("-+-".join("-" * width for width in widths))

    for filename, counts in rows:
        values = [filename, *[str(counts[level]) for level in LOG_LEVELS]]
        print(" | ".join(value.ljust(width) for value, width in zip(values, widths)).rstrip())


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Count INFO, WARN, ERROR, and DEBUG occurrences in .log files."
    )

    parser.add_argument(
        "directory",
        type=Path,
        help="Directory containing .log files",
    )

    parser.add_argument(
        "--min-errors",
        type=int,
        default=0,
        metavar="N",
        help="Only show files with at least N ERROR occurrences (default: 0)",
    )

    args = parser.parse_args()

    if not args.directory.exists():
        parser.error(f"directory does not exist: {args.directory}")

    if not args.directory.is_dir():
        parser.error(f"not a directory: {args.directory}")

    if args.min_errors < 0:
        parser.error("--min-errors must be a non-negative integer")

    rows = []

    for path in sorted(args.directory.glob("*.log"), key=lambda item: item.name):
        if not path.is_file():
            continue

        counts = count_log_levels(path)

        if counts["ERROR"] >= args.min_errors:
            rows.append((path.name, counts))

    print_summary(rows)


if __name__ == "__main__":
    main()
